// Differential probe for the pinned examples/jsm/geometries/TeapotGeometry.js port.
//
// Protocol: one scenario per stdin line, tokens separated by spaces. The scenario list is
// generated by compare-teapot-geometry.mjs, which replays the same calls against the pinned
// three.js module, so the field order below is the single source of truth for both sides.
//
//   defaults
//   teapot <size> <segments> <bottom> <lid> <body> <fitLid> <blinn>
//
// `defaults` builds `new TeapotGeometry()` on both sides, which pins the constructor defaults of
// the native header to the upstream parameter list. The five flags travel as 0/1 and are read
// with JavaScript truthiness; `segments` accepts the shared NaN token (Math.max propagates it
// while std::max would not, and the upstream loop then produces empty buffers).
//
// Every scenario reports the position/normal/uv attributes (count, itemSize, normalized and the
// stored float32 components), the index nullness and the index array, `type`, the JSON fields a
// parameterized geometry would add (the pinned class assigns no `parameters`, so only `type`
// exists) and the computeBoundingSphere() result.
//
// Numbers use the shared encoding of the other probes: NaN, -0, Infinity and -Infinity travel
// as those four strings.
#include "core/BufferAttribute.h"
#include "core/BufferGeometry.h"
#include "core/JsonValue.h"
#include "geometries/TeapotGeometry.h"
#include <charconv>
#include <cmath>
#include <cstddef>
#include <iostream>
#include <limits>
#include <memory>
#include <sstream>
#include <stdexcept>
#include <string>

namespace {

JsonValue number(double value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return value < 0 ? "-Infinity" : "Infinity";
    if (value == 0 && std::signbit(value)) return "-0";
    return value;
}
double parse(const std::string& token) {
    if (token == "NaN") return std::numeric_limits<double>::quiet_NaN();
    if (token == "Infinity") return std::numeric_limits<double>::infinity();
    if (token == "-Infinity") return -std::numeric_limits<double>::infinity();
    if (token == "-0") return -0.;
    double value = 0;
    std::from_chars(token.data(), token.data() + token.size(), value);
    return value;
}

struct Reader {
    std::istringstream stream;
    explicit Reader(const std::string& line) : stream(line) {}
    std::string token() {
        std::string value;
        stream >> value;
        return value;
    }
    double numberToken() { return parse(token()); }
};

JsonValue arrayJSON(const InterpolantArray& array) {
    JsonValue::Array values;
    for (std::size_t i = 0, length = array.size(); i < length; ++i)
        values.push_back(number(array.number(double(i))));
    return values;
}
// A missing attribute is reported as null instead of dereferencing it, so a port that drops one
// shows up as a diff rather than as a probe crash.
JsonValue attributeJSON(const std::shared_ptr<VertexAttribute>& attribute) {
    if (!attribute) return JsonValue(nullptr);
    return JsonValue::Object{{"count", number(attribute->getCount())},
                             {"itemSize", number(attribute->getItemSize())},
                             {"normalized", attribute->getNormalized()},
                             {"values", arrayJSON(attribute->getArray())}};
}

JsonValue geometryState(const TeapotGeometry& geometry) {
    JsonValue result = JsonValue::Object{};
    result["position"] = attributeJSON(geometry.getAttribute("position"));
    result["normal"] = attributeJSON(geometry.getAttribute("normal"));
    result["uv"] = attributeJSON(geometry.getAttribute("uv"));
    result["hasIndex"] = geometry.index != nullptr;
    result["index"] = geometry.index ? arrayJSON(geometry.index->getArray()) : JsonValue(nullptr);
    result["type"] = geometry.type;

    // The pinned class never assigns `parameters`, so BufferGeometry#toJSON carries none of the
    // fields a parameterized geometry would add; only `type` exists on both sides.
    const JsonValue json = geometry.toJSON();
    JsonValue fields = JsonValue::Object{};
    for (const auto& name : {"size", "segments", "bottom", "lid", "body", "fitLid", "blinn"})
        if (json.contains(name)) fields[name] = json.at(name);
    fields["type"] = json.at("type");
    result["json"] = std::move(fields);

    if (geometry.boundingSphere)
        result["boundingSphere"] = JsonValue::Object{
            {"center", JsonValue::Array{number(geometry.boundingSphere->center.x),
                                        number(geometry.boundingSphere->center.y),
                                        number(geometry.boundingSphere->center.z)}},
            {"radius", number(geometry.boundingSphere->radius)}};
    else result["boundingSphere"] = JsonValue(nullptr);
    return result;
}

JsonValue runScenario(const std::string& line) {
    Reader reader(line);
    const std::string kind = reader.token();

    if (kind == "defaults") return geometryState(TeapotGeometry());

    if (kind == "teapot") {
        const double size = reader.numberToken();
        const double segments = reader.numberToken();
        const bool bottom = reader.numberToken() != 0;
        const bool lid = reader.numberToken() != 0;
        const bool body = reader.numberToken() != 0;
        const bool fitLid = reader.numberToken() != 0;
        const bool blinn = reader.numberToken() != 0;
        return geometryState(TeapotGeometry(size, segments, bottom, lid, body, fitLid, blinn));
    }

    throw std::runtime_error("unknown scenario kind: " + kind);
}

} // namespace

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        try {
            std::cout << runScenario(line).dump() << '\n';
        } catch (const std::exception& error) {
            std::cout << JsonValue(JsonValue::Object{{"probeError", error.what()}}).dump() << '\n';
        }
    }
    return 0;
}
